const $=(s,r=document)=>r.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>Math.random().toString(36).slice(2,9);
const num=(v,d=0)=>{const x=parseFloat(String(v??'').replace(/\s/g,'').replace(',','.'));return isNaN(x)?d:x};
const r2=v=>Math.round(v*100)/100;
const N0=new Intl.NumberFormat('fr-FR',{maximumFractionDigits:0}),N2=new Intl.NumberFormat('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2});
const z=v=>Math.abs(v)<0.005?0:v;
const n0=v=>N0.format(z(v)),n2=v=>N2.format(z(v)),e0=v=>n0(v)+' €',e2=v=>n2(v)+' €';
const todayISO=new Date().toLocaleDateString('sv-SE');
const MONTHS=['janv.','févr.','mars','avr.','mai','juin','juil.','août','sept.','oct.','nov.','déc.'];
const dparts=s=>s.split('-').map(Number);
function addDays(iso,n){const d=new Date(iso+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
function addMonths(iso,n){const [y,m,d]=dparts(iso);const t=y*12+(m-1)+n,yy=Math.floor(t/12),mm=t%12;const dim=new Date(Date.UTC(yy,mm+1,0)).getUTCDate();return `${yy}-${String(mm+1).padStart(2,'0')}-${String(Math.min(d,dim)).padStart(2,'0')}`}
const fdate=s=>{const [y,m,d]=dparts(s);return `${String(d).padStart(2,'0')}/${String(m).padStart(2,'0')}/${y}`};
/* paires HT / TTC */
const P=(h=0,t=0)=>({h,t});
const padd=(...a)=>a.reduce((x,y)=>P(x.h+y.h,x.t+y.t),P());
const psub=(a,b)=>P(a.h-b.h,a.t-b.t);
const pmul=(a,k)=>P(a.h*k,a.t*k);
const ratio=(p,d)=>Math.abs(p.h)>0.005?p.t/p.h:d;

