/* briques d'affichage */
const dual=(p,f=n0)=>`<div class="dual"><span class="h">${f(p.h)}</span><span class="t">${f(p.t)}</span></div>`;
const tags='<span class="tags"><i class="h">HT</i><i class="t">TTC</i></span>';
const kpi=(l,p,sub='')=>`<div class="kpi"><div class="kl">${l}</div><div class="kv"><span class="h">${e0(p.h)}</span><span class="tag h">HT</span></div><div class="kv"><span class="t">${e0(p.t)}</span><span class="tag t">TTC</span></div>${sub?`<div class="ks">${sub}</div>`:''}</div>`;
const head=(t,l)=>`<div class="pagehead"><h1>${t}</h1><p class="lead">${l}</p></div>`;
const fld=(l,inner,c='f')=>`<div class="field ${c}"><label>${l}</label>${inner}</div>`;
const inp=(p,v,extra='')=>`<input type="text" inputmode="decimal" autocomplete="off" data-draft="${p}" value="${esc(v)}" ${extra}>`;
const sel=(p,opts,v,extra='')=>`<select data-draft="${p}" ${extra}>${opts.map(([k,l])=>`<option value="${esc(k)}"${String(k)===String(v)?' selected':''}>${esc(l)}</option>`).join('')}</select>`;
const rateOpts=RATES.map(r=>[r,r+' %']);
const bindIn=(p,v,ph='')=>`<input type="text" inputmode="decimal" data-bind="${p}" data-num="1" value="${esc(v)}" placeholder="${esc(ph)}">`;
const avgRate=()=>{const s=yearStats(S.settings.year);return ratio(s.ca,1+0.2)};
function niceStep(x){const m=Math.pow(10,Math.floor(Math.log10(x||1))),r=x/m;return(r<=1?1:r<=2?2:r<=5?5:10)*m}
function lineChart(series,labels){const w=760,h=250,pd={l:64,r:14,t:12,b:26};const all=series.flatMap(s=>s.v);let mn=Math.min(0,...all),mx=Math.max(0,...all);if(mx===mn)mx=mn+1;
const st=niceStep((mx-mn)/4);mn=Math.floor(mn/st)*st;mx=Math.ceil(mx/st)*st;
const X=i=>pd.l+(w-pd.l-pd.r)*i/(labels.length-1),Y=v=>pd.t+(h-pd.t-pd.b)*(1-(v-mn)/(mx-mn));let g='';
for(let v=mn;v<=mx+st/1000;v+=st)g+=`<line x1="${pd.l}" x2="${w-pd.r}" y1="${Y(v)}" y2="${Y(v)}" stroke="${Math.abs(v)<1e-9?'var(--line2)':'var(--line)'}" ${Math.abs(v)<1e-9?'stroke-width="1.5"':'stroke-dasharray="2 5"'}/><text class="ax" x="${pd.l-6}" y="${Y(v)+4}" text-anchor="end">${n0(v)}</text>`;
labels.forEach((l,i)=>g+=`<text class="ax" x="${X(i)}" y="${h-8}" text-anchor="middle">${l}</text>`);
const gid='g'+Math.random().toString(36).slice(2,7);let defs='';series.forEach((s,k)=>{const d=s.v.map((v,i)=>`${i?'L':'M'}${X(i).toFixed(1)} ${Y(v).toFixed(1)}`).join(' '),b=Y(Math.max(mn,0)),lx=X(s.v.length-1),ly=Y(s.v[s.v.length-1]);defs+=`<linearGradient id="${gid}${k}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" style="stop-color:${s.c};stop-opacity:.22"/><stop offset="1" style="stop-color:${s.c};stop-opacity:0"/></linearGradient>`;g+=`<path d="${d} L${lx.toFixed(1)} ${b.toFixed(1)} L${X(0).toFixed(1)} ${b.toFixed(1)}Z" fill="url(#${gid}${k})"/><path d="${d}" fill="none" stroke="${s.c}" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round"/><circle cx="${lx}" cy="${ly}" r="8" style="fill:${s.c};fill-opacity:.16"/><circle cx="${lx}" cy="${ly}" r="4" style="fill:${s.c}" stroke="var(--surface)" stroke-width="1.5"/>`});g=`<defs>${defs}</defs>`+g;
return `<svg class="ch" viewBox="0 0 ${w} ${h}" role="img" aria-label="Graphique">${g}</svg>`}

/* ===== COMPTABILITÉ AUTOMATIQUE ===== */
function journal(y){const L=[];const push=(date,j,a,label,d,c)=>{if(+date.slice(0,4)===y&&(Math.abs(d)>0.004||Math.abs(c)>0.004))L.push({date,j,a,label,d,c})};
S.entries.forEach(e=>{const v=e.ht*e.rate/100,T=e.ht+v,pay=e.paid||addDays(e.date,e.delay||0);
if(e.kind==='vente'){push(e.date,'VT','411',e.label,T,0);push(e.date,'VT',e.cat,e.label,0,e.ht);push(e.date,'VT','44571','TVA '+e.rate+' % – '+e.label,0,v);push(pay,'BQ','512',e.label,T,0);push(pay,'BQ','411',e.label,0,T)}
else{const tier=e.kind==='immo'?'404':'401',tv=e.kind==='immo'?'44562':'44566';push(e.date,'AC',e.cat,e.label,e.ht,0);push(e.date,'AC',tv,'TVA '+e.rate+' % – '+e.label,v,0);push(e.date,'AC',tier,e.label,0,T);push(pay,'BQ',tier,e.label,T,0);push(pay,'BQ','512',e.label,0,T)}});
S.loans.forEach(l=>{push(l.start,'BQ','512',l.label,l.amount,0);push(l.start,'BQ','164',l.label,0,l.amount);sched(l).forEach(r=>{push(r.date,'BQ','164',l.label+' – capital',r.capital,0);push(r.date,'BQ','661',l.label+' – intérêts',r.interest,0);push(r.date,'BQ','512',l.label+' – échéance',0,r.capital+r.interest)})});
S.equity.forEach(q=>{push(q.date,'BQ','512',q.label,q.amount,0);push(q.date,'BQ',{apport:'101',compte:'455',subvention:'131'}[q.type],q.label,0,q.amount)});
assets().forEach(({e,p})=>{const d=p[y]||0;push(y+'-12-31','OD','681','Dotation – '+e.label,d,0);push(y+'-12-31','OD',amAcc(e.cat),'Amortissement – '+e.label,0,d)});
return L.sort((a,b)=>a.date.localeCompare(b.date)||a.j.localeCompare(b.j))}

function viewCompta(){const y=S.settings.year,d=drafts.entry,sub=ui.sub;
let h=head('Comptabilité automatique','Saisissez une pièce : le journal, la TVA, la balance et le compte de résultat se génèrent seuls. Chaque montant est tenu en HT et en TTC.');
if(S.demo)h+=`<div class="banner"><span>Données d'exemple affichées. Remplacez-les par les vôtres.</span><button data-act="clear-demo">Effacer les exemples et repartir de zéro</button></div>`;
h+=`<div class="sub">${[['saisie','Saisie des pièces'],['import','Import bancaire'],['modeles','Modèles récurrents'],['journal','Journal'],['balance','Balance'],['resultat','Résultat et TVA']].map(([k,l])=>`<button data-act="sub" data-v="${k}" class="${sub===k?'on':''}">${l}</button>`).join('')}</div>`;
if(sub==='saisie')h+=entryForm(d)+entryList(y);
if(sub==='import')h+=viewImport();if(sub==='modeles')h+=viewTpl();if(sub==='journal')h+=viewJournal(y);
if(sub==='balance')h+=viewBalance(y);
if(sub==='resultat')h+=viewResultat(y);
return h}
