const docTot=D=>D.lines.reduce((a,l)=>{const h=num(l.q)*num(l.pu),v=h*num(l.rate)/100;return P(a.h+h,a.t+h+v)},P());
const dueOf=D=>addDays(D.date,D.terms||0);
function nextNum(type,date){const y=date.slice(0,4);const n=S.docs.filter(d=>d.type===type&&d.date.slice(0,4)===y).length+1;return `${PFX[type]}-${y}-${String(n).padStart(3,'0')}`}
const docLate=D=>D.type==='facture'&&D.status==='envoyé'&&dueOf(D)<todayISO;
