function tiersStats(y,vente){const m={};S.entries.forEach(e=>{if(+e.date.slice(0,4)!==y||(e.kind==='vente')!==vente)return;const k=e.tiers||'(sans nom)',o=m[k]||(m[k]={t:P(),open:P(),d:[]});const p=P(e.ht,tt(e));o.t=padd(o.t,p);if(!e.paid&&e.date<=todayISO)o.open=padd(o.open,p);if(e.paid)o.d.push((Date.parse(e.paid)-Date.parse(e.date))/864e5)});return m}
