const BAREME=[[11600,0],[29579,.11],[84577,.30],[181917,.41],[Infinity,.45]];
function irCalc(imp,parts){parts=Math.max(1,parts||1);const q=Math.max(0,imp)/parts;let t=0,lo=0;for(const [hi,r] of BAREME){if(q>lo)t+=(Math.min(q,hi)-lo)*r;lo=hi}return t*parts}
const isCalc=b=>b>0?0.15*Math.min(b,42500)+0.25*Math.max(0,b-42500):0;
function chargesExp(y){let c=0;E().forEach(e=>{if(+e.date.slice(0,4)===y&&(e.kind==='varia'||e.kind==='fixe')&&!['641','645'].includes(e.cat))c+=e.ht});return c+dotYear(y).h+loanYear(y).int}
function simStatuts(){const f=S.fl,y=S.settings.year,s=yearStats(y),CA=ov(f.ca)?+f.ca:s.ca.h,CH=ov(f.ch)?+f.ch:chargesExp(y),B=CA-CH,parts=f.parts||1,tns=(f.tns??45)/100,pat=(f.pat??42)/100,sal=(f.sal??22)/100,pfu=(f.pfu??31.4)/100,rm=(f.remu??60)/100;
const o={};
const mc=CA*(f.tmicro??25.6)/100,mi=irCalc(CA*(1-(f.abat??34)/100),parts);
o.micro={label:'Micro-entreprise',cot:mc,imp:mi,is:0,div:0,net:CA-CH-mc-mi,ok:CA<=(f.plafond??83600),note:CA<=(f.plafond??83600)?'Charges non déductibles : seul l\'abattement s\'applique.':'Plafond de chiffre d\'affaires dépassé.'};
const ce=Math.max(0,B)*tns/(1+tns),ie=irCalc(B-ce,parts);o.ei={label:'EI au réel',cot:ce,imp:ie,is:0,div:0,net:B-ce-ie,ok:true,note:'Charges déductibles, cotisations sur le bénéfice.'};
const mk=(label,cost,pc)=>{const R=Math.max(0,B)*rm,net0=R/(1+pc),cot=R-net0,irr=irCalc(net0*0.9,parts),pr=Math.max(0,B)-R,is=isCalc(pr),div=pr-is;return{label,cot,imp:irr+div*pfu,is,div,net:net0-irr+div*(1-pfu),ok:true,note:'Rémunération : '+Math.round(rm*100)+' % du résultat, le reste en dividendes (flat tax).'}};
o.eurl=mk('EURL à l\'IS',0,tns);
{const R=Math.max(0,B)*rm,brut=R/(1+pat),net0=brut*(1-sal),cot=R-net0,irr=irCalc(net0*0.9,parts),pr=Math.max(0,B)-R,is=isCalc(pr),div=pr-is;o.sasu={label:'SASU à l\'IS',cot,imp:irr+div*pfu,is,div,net:net0-irr+div*(1-pfu),ok:true,note:'Charges patronales '+Math.round(pat*100)+' %, salariales '+Math.round(sal*100)+' %, dividendes sans cotisations.'}}
return{o,CA,CH,B}}
function docsDays(y){let d=0,h=0;S.docs.forEach(D=>{if(D.type==='facture'&&D.status!=='brouillon'&&+D.date.slice(0,4)===y)D.lines.forEach(l=>{if((l.u||'').toLowerCase().startsWith('jour')){d+=num(l.q);h+=num(l.q)*num(l.pu)}})});return{d,h}}
function viewFreelance(){const f=S.fl,y=S.settings.year,sim=simStatuts(),c=srCalc(),kv=c.kv;
const jf=Math.max(1,365-104-num(f.feries??8)-num(f.conges??25)),jb=Math.round(jf*(1-num(f.nonfact??20)/100)),R=num(S.goal.result),req=c.tm>0?(c.cfH+R)/c.tm:0,tjmMin=req/jb,dd=docsDays(y);
const pl=num(f.plafond??83600),sm=sim.CA;
let h=head('Freelance UI/UX','Votre TJM minimum, la comparaison des statuts, vos seuils réglementaires et l\'argent à mettre de côté. Les taux sont des estimations 2026 à vérifier auprès de l\'URSSAF et des impôts.');
h+=`<div class="grid">${kpi('TJM minimum pour votre objectif',P(tjmMin,tjmMin*kv),'Sur '+jb+' jours facturables')}${kpi('TJM moyen réalisé',dd.d>0?P(dd.h/dd.d,dd.h/dd.d*kv):P(),dd.d>0?n0(dd.d)+' jours facturés '+y:'Facturez en « jour » dans Facturation')}<div class="kpi"><div class="kl">Taux d'occupation</div><div class="kv"><span class="h">${n0(dd.d/jb*100)} %</span></div><div class="ks">${n0(dd.d)} jours facturés sur ${jb} possibles</div></div>${kpi('TJM actuel de référence',P(num(f.tjm),num(f.tjm)*kv))}</div>`;
h+=`<div class="card"><h2>Capacité de travail</h2><div class="row">${fld('Congés (jours)',bindIn('fl.conges',f.conges))}${fld('Jours fériés ouvrés',bindIn('fl.feries',f.feries))}${fld('Temps non facturé (%)',bindIn('fl.nonfact',f.nonfact))}${fld('TJM de référence HT (€)',bindIn('fl.tjm',f.tjm))}</div><p class="note">Jours facturables = 365 − 104 week-ends − fériés − congés, réduits du temps de prospection, d'administratif et de formation. Le résultat visé se règle dans Objectif de vente.</p></div>`;
h+=`<div class="card"><h2>Seuils réglementaires ${y}</h2><div class="two"><div><div class="kl">Plafond micro-entreprise (${e0(pl)} HT)</div><div class="bar"><div style="width:${Math.min(100,sm/pl*100)}%"></div></div><p class="note">${e0(sm)} HT, ${n0(sm/pl*100)} % du plafond.</p></div><div><div class="kl">Franchise en base de TVA (37 500 € HT, tolérance 41 250 €)</div><div class="bar"><div style="width:${Math.min(100,sm/41250*100)}%"></div></div><p class="note">${sm>41250?'Seuil majoré dépassé : TVA due dès le 1er jour du mois de dépassement.':sm>37500?'Seuil dépassé, dans la tolérance : TVA due l\'année suivante.':'Sous le seuil de franchise.'}</p></div></div></div>`;
const row=k=>{const x=sim.o[k];return `<tr class="${x.net===Math.max(...Object.values(sim.o).filter(q=>q.ok).map(q=>q.net))&&x.ok?'strong':''}"><td class="l">${x.label}${x.ok?'':' <span class="chip bad">hors plafond</span>'}<br><span class="note" style="margin:0">${esc(x.note)}</span></td><td>${dual(P(x.cot,x.cot))}</td><td>${dual(P(x.is,x.is))}</td><td>${dual(P(x.imp,x.imp))}</td><td>${dual(P(x.net,x.net))}</td><td class="num">${dual(P(x.net/12,x.net/12))}</td><td class="num">${sim.CA>0?n0(x.net/sim.CA*100)+' %':'-'}</td></tr>`};
h+=`<div class="card"><h2>Comparaison des statuts, exercice ${y}</h2><div class="grid" style="margin-bottom:12px">${kpi('Chiffre d\'affaires',P(sim.CA,sm*0+s2(sim.CA)))}${kpi('Charges d\'exploitation',P(sim.CH,sim.CH*ratio(yearStats(y).cf,1.2)))}</div><div class="scroll"><table class="t"><thead><tr><th class="l">Statut</th><th>Cotisations</th><th>Impôt société</th><th>Impôt revenu et flat tax</th><th>Net en poche par an</th><th>Net par mois</th><th>% du CA</th></tr></thead><tbody>${['micro','ei','eurl','sasu'].map(row).join('')}</tbody></table></div>
<p class="note">Net en poche = ce qui reste après charges, cotisations et impôts. Aucune TVA sur ces postes : HT et TTC sont identiques. Ligne en gras : le net le plus élevé.</p>
<div class="row" style="margin-top:8px">${fld('Part du résultat versée en rémunération (%)',bindIn('fl.remu',f.remu??60))}${fld('Parts fiscales',bindIn('fl.parts',f.parts??1))}${fld('CA simulé (€ HT)',bindIn('fl.ca',f.ca??'',n0(sim.CA)))}${fld('Charges simulées (€ HT)',bindIn('fl.ch',f.ch??'',n0(sim.CH)))}</div>
<details style="margin-top:10px"><summary>Taux utilisés (modifiables)</summary><div class="row" style="margin-top:8px">${fld('Cotisations micro BNC (%)',bindIn('fl.tmicro',f.tmicro??25.6))}${fld('Abattement micro BNC (%)',bindIn('fl.abat',f.abat??34))}${fld('Plafond micro (€)',bindIn('fl.plafond',f.plafond??83600))}${fld('Cotisations TNS (% du net)',bindIn('fl.tns',f.tns??45))}${fld('Charges patronales SASU (%)',bindIn('fl.pat',f.pat??42))}${fld('Charges salariales SASU (%)',bindIn('fl.sal',f.sal??22))}${fld('Flat tax dividendes (%)',bindIn('fl.pfu',f.pfu??31.4))}</div></details></div>`;
const k=f.statut||'sasu',x=sim.o[k]||sim.o.sasu,rate=sim.CA>0?(x.cot+x.imp+x.is)/sim.CA:0,vat=ratio(yearStats(y).ca,1)-1;
h+=`<div class="card"><h2>Argent à mettre de côté</h2><div class="row">${fld('Statut',`<select data-bind="fl.statut">${[['micro','Micro-entreprise'],['ei','EI au réel'],['eurl','EURL à l\'IS'],['sasu','SASU à l\'IS']].map(([a,b])=>`<option value="${a}"${k===a?' selected':''}>${b}</option>`).join('')}</select>`)}</div>
<p>Pour chaque <b>100 € HT</b> encaissés (soit <b>${n2(100*(1+vat))} € TTC</b>) : gardez <b>${n2(100*vat)} €</b> pour la TVA et <b>${n2(100*rate)} €</b> pour cotisations et impôts. Il vous reste environ <b>${n2(100*(1-rate))} € HT</b>, avant vos charges.</p>
<p class="note">Estimation à partir du statut choisi. Ouvrez un compte épargne dédié et alimentez-le à chaque encaissement.</p></div>`;
return h}
