function gameStats(g){const o={cost:P(),costDone:P(),rev:P(),revNet:0,elig:0};S.entries.forEach(e=>{if(e.act!==g.name)return;const p=P(e.ht,tt(e));if(e.kind==='vente'){o.rev=padd(o.rev,p);if(['7071','7072','7073','7074','7065','7066'].includes(e.cat))o.revNet+=e.ht}else{o.cost=padd(o.cost,p);if(e.date<=todayISO)o.costDone=padd(o.costDone,p);if(CIJV_CATS.includes(e.cat))o.elig+=e.ht}});return o}
