<div class="row" style="margin-top:12px">${fld('Aides déjà acquises (€)',bindIn('games.'+S.games.indexOf(g)+'.aides',g.aides))}${fld('Avance éditeur (€)',bindIn('games.'+S.games.indexOf(g)+'.avance',g.avance))}${fld('Unités sur 24 mois',bindIn('games.'+S.games.indexOf(g)+'.units',g.units))}${fld('Rétention mensuelle des ventes (%)',bindIn('games.'+S.games.indexOf(g)+'.decay',g.decay))}${fld('Part éligible CIJV (%)',bindIn('games.'+S.games.indexOf(g)+'.cijvPart',g.cijvPart))}</div>
