/* équipe et runway */
function runway(){const y=S.settings.year,T=treasury(y),now=new Date(),cur=now.getFullYear()===y?now.getMonth():(y<now.getFullYear()?11:0),i=Math.min(11,Math.max(0,cur));
const rng=[];for(let k=Math.max(0,i-2);k<=i;k++)rng.push(k);const out=sum(rng.map(k=>T.cvT[k]+T.cfT[k]+T.pay[k]+T.isP[k]+T.cap[k]+T.int[k]))/rng.length,inn=sum(rng.map(k=>T.vT[k]))/rng.length,burn=Math.max(0,out-inn);
return{cash:T.bT[i],cashH:T.bH[i],burn,out,inn,months:burn>0?Math.max(0,T.bT[i])/burn:Infinity,mi:i}}
function viewEquipe(){const d=drafts.mem,rw=runway();let h=head('Équipe et runway','Masse salariale, prestataires, coût mensuel de l\'équipe et durée de vie de la trésorerie.');
const masse=S.team.reduce((a,m)=>{const c=m.type==='salarié'?empM(m):num(m.amount),t=m.type==='salarié'?c:c*(1+num(m.rate)/100);return padd(a,P(c,t))},P());
h+=`<div class="grid">${kpi('Coût mensuel de l\'équipe',masse,S.team.length+' personne(s)')}${kpi('Trésorerie ('+MONTHS[rw.mi]+')',P(rw.cashH,rw.cash))}${kpi('Consommation mensuelle nette (burn)',P(rw.burn,rw.burn),'Décaissements moins ventes, moyenne sur 3 mois')}<div class="kpi"><div class="kl">Runway</div><div class="kv"><span class="h">${isFinite(rw.months)?n2(rw.months)+' mois':'Rentable'}</span></div><div class="ks">${isFinite(rw.months)?(rw.months<6?'<span class="chip bad">Moins de 6 mois</span>':rw.months<12?'<span class="chip warn">Moins de 12 mois</span>':'<span class="chip good">Confortable</span>'):'Les ventes couvrent les dépenses'}</div></div></div>`;
h+=`<div class="card"><h2>Nouveau membre</h2><div class="row">${fld('Nom ou poste',inp('mem.name',d.name),'f2')}${fld('Statut',sel('mem.type',[['salarié','Salarié'],['prestataire','Prestataire']],d.type))}${fld(d.type==='salarié'?'Salaire brut mensuel (€)':'Coût mensuel HT (€)',inp('mem.amount',d.amount))}${d.type==='salarié'?fld('Charges patronales (%)',inp('mem.pat',d.pat))+fld('Calcul des charges',sel('mem.mode',[['taux','Taux unique'],['reel','Paie réelle (RGDU, JEI)']],d.mode)):fld('TVA',sel('mem.rate',rateOpts,d.rate))}${fld('Début',`<input type="date" data-draft="mem.start" value="${d.start}">`)}${fld('Fin (facultatif)',`<input type="date" data-draft="mem.end" value="${d.end}">`)}${fld('Jeu',`<input type="text" data-draft="mem.act" list="acts" value="${esc(d.act)}"><datalist id="acts">${actNames().map(a=>`<option value="${esc(a)}">`).join('')}</datalist>`)}<button class="pri" data-act="add-mem">Ajouter</button></div></div>
<div class="card"><h2>Équipe (${S.team.length})</h2><div class="scroll"><table class="t"><thead><tr><th class="l">Nom</th><th class="l">Statut</th><th class="l">Période</th><th class="l">Jeu</th><th>Coût mensuel</th><th></th></tr></thead><tbody>${S.team.map(m=>{const c=m.type==='salarié'?empM(m):num(m.amount),t=m.type==='salarié'?c:c*(1+num(m.rate)/100);return `<tr><td class="l">${esc(m.name)}</td><td class="l">${m.type}</td><td class="l num">${fdate(m.start)} → ${m.end?fdate(m.end):'en cours'}</td><td class="l">${esc(m.act||'-')}</td><td>${dual(P(c,t))}</td><td><button class="lnk" data-act="gen-team" data-id="${m.id}">Générer les pièces</button><button class="lnk danger" data-act="del-mem" data-id="${m.id}">Suppr.</button></td></tr>`}).join('')||'<tr><td colspan="6" class="l" style="color:var(--muted)">Aucun membre.</td></tr>'}</tbody></table></div>
<div class="row" style="margin-top:10px"><button class="pri" data-act="gen-team-all">Générer toutes les pièces jusqu'à fin ${S.settings.year}</button></div><p class="note">Pour un salarié : le salaire brut et les charges patronales sont créés chaque mois en comptabilité, sans TVA. Un prestataire est créé en charge variable, payé à 30 jours. Aucun doublon n'est créé si vous relancez.</p></div>`;return h}
function genTeam(m){const end=S.settings.year+'-12-31',stop=m.end&&m.end<end?m.end:end;let n=0;for(let k=0;k<120;k++){const dt=addMonths(m.start,k);if(dt>stop)break;if(S.locked[+dt.slice(0,4)])continue;const key='team|'+m.id+'|'+dt.slice(0,7);if(S.entries.some(e=>(e.tpl||'').startsWith(key)||(e.date.slice(0,7)===dt.slice(0,7)&&(e.label==='Salaire – '+m.name||e.label==='Prestataire – '+m.name))))continue;
if(m.type==='salarié'){const b=num(m.amount);S.entries.push({id:uid(),date:dt,label:'Salaire – '+m.name,kind:'fixe',cat:'641',ht:b,rate:0,delay:0,dur:3,mode:'lin',act:m.act||'',tpl:key+'|a'},{id:uid(),date:dt,label:'Charges patronales – '+m.name,kind:'fixe',cat:'645',ht:r2(empM(m)-b),rate:0,delay:0,dur:3,mode:'lin',act:m.act||'',tpl:key+'|b'})}
else S.entries.push({id:uid(),date:dt,label:'Prestataire – '+m.name,kind:'varia',cat:S.profile==='game'?'6112':'6045',ht:num(m.amount),rate:num(m.rate),delay:30,dur:3,mode:'lin',act:m.act||'',tpl:key+'|a'});n++}return n}
