function viewCal(){const y=S.settings.year,st=S.settings,T=treasury(y),L=[],add=(date,label,p,t)=>L.push({date,label,p,t});
if(st.tvaRegime!=='franchise')T.pay.forEach((v,m)=>{if(v>0.5)add(`${y}-${String(m+1).padStart(2,'0')}-20`,'Déclaration et paiement de la TVA (CA3)',P(v,v),'TVA')});
if(T.due>0)add(`${y+1}-01-20`,'TVA de décembre à payer',P(T.due,T.due),'TVA');
if(st.tax==='is'){const i1=yearStats(y-1).is.h,i2=yearStats(y-2).is.h;[['03','15'],['06','15'],['09','15'],['12','15']].forEach(([m,d])=>{if(i1>0)add(`${y}-${m}-${d}`,'Acompte d\'impôt sur les sociétés',P(i1/4,i1/4),'IS')});if(i1-i2>0)add(`${y}-05-15`,'Solde d\'impôt sur les sociétés '+(y-1),P(i1-i2,i1-i2),'IS');add(`${y}-05-15`,'Dépôt de la liasse fiscale et des comptes '+(y-1),P(),'Dossier')}
add(`${y}-12-15`,'Cotisation foncière des entreprises (CFE), à estimer',P(num(st.cfe),num(st.cfe)),'Taxe');
S.loans.forEach(l=>sched(l).forEach(r=>{if(+r.date.slice(0,4)===y)add(r.date,'Échéance : '+l.label,P(r.capital+r.interest,r.capital+r.interest),'Prêt')}));
unpaid().filter(x=>x.due>=todayISO).forEach(x=>add(x.due,(x.e.kind==='vente'?'Encaissement attendu : ':'Paiement à effectuer : ')+x.e.label,P(x.e.ht,tt(x.e)),x.e.kind==='vente'?'Client':'Fournisseur'));
if(S.profile==='ux'&&S.fl.statut==='micro')['04-30','07-31','10-31'].forEach(d=>add(`${y}-${d}`,'Déclaration du chiffre d\'affaires à l\'URSSAF',P(),'URSSAF'));
L.sort((a,b)=>a.date.localeCompare(b.date));const up=L.filter(x=>x.date>=todayISO||+x.date.slice(0,4)!==new Date().getFullYear());
return head('Calendrier fiscal et échéances','Toutes vos échéances de '+y+' : TVA, impôt, prêts, encaissements et paiements attendus, avec les montants calculés.')+`<div class="card"><div class="row">${fld('CFE estimée (€)',bindIn('settings.cfe',st.cfe??0))}</div><div class="scroll"><table class="t" style="margin-top:8px"><thead><tr><th class="l">Date</th><th class="l">Échéance</th><th class="l">Type</th><th>Montant</th></tr></thead><tbody>${L.map(x=>`<tr style="${x.date<todayISO?'opacity:.55':''}"><td class="l num">${fdate(x.date)}</td><td class="l">${esc(x.label)}</td><td class="l"><span class="chip">${x.t}</span></td><td>${x.p.t||x.p.h?dual(x.p):'<span class="note">-</span>'}</td></tr>`).join('')}</tbody></table></div><p class="note">Les dates des déclarations sont indicatives : vérifiez votre calendrier sur impots.gouv.fr. Les lignes grisées sont passées.</p></div>`}

/* ===== BILAN SIMPLIFIÉ ===== */
function viewBilan(){const y=S.settings.year,m={};for(let yy=minYear();yy<=y;yy++)journal(yy).forEach(l=>{const o=m[l.a]||(m[l.a]={d:0,c:0});o.d+=l.d;o.c+=l.c});
const bal=p=>Object.keys(m).filter(a=>a.startsWith(p)).reduce((s,a)=>s+m[a].d-m[a].c,0),sd=a=>m[a]?m[a].d-m[a].c:0;
const pr=Object.keys(m).filter(a=>/^7/.test(a)).reduce((s,a)=>s+m[a].c-m[a].d,0),ch=Object.keys(m).filter(a=>/^6/.test(a)).reduce((s,a)=>s+m[a].d-m[a].c,0),rai=pr-ch;let is=0;for(let yy=minYear();yy<=y;yy++)is+=yearStats(yy).is.h;
const immo=Object.keys(m).filter(a=>/^2[01]|^2[0-9]/.test(a)&&!a.startsWith('28')).reduce((s,a)=>s+Math.max(0,sd(a)),0),am=-Object.keys(m).filter(a=>a.startsWith('28')).reduce((s,a)=>s+sd(a),0);
const cli=Math.max(0,sd('411')),bq=sd('512'),tvaN=sd('44571')+sd('44566')+sd('44562'),tvaA=Math.max(0,tvaN),tvaP=Math.max(0,-tvaN),fo=Math.max(0,-sd('401')),fi=Math.max(0,-sd('404')),emp=Math.max(0,-sd('164')),cap=-sd('101'),cc=-sd('455'),sub=-sd('131');
const act=[['Immobilisations nettes',P(immo-am,immo-am)],['Créances clients',P(cli,cli)],['TVA à récupérer',P(tvaA,tvaA)],['Banque',P(Math.max(0,bq),Math.max(0,bq))]],pas=[['Capital',P(cap,cap)],['Comptes courants d\'associés',P(cc,cc)],['Subventions d\'investissement',P(sub,sub)],['Résultat net cumulé',P(rai-is,rai-is)],['Emprunts',P(emp,emp)],['Dettes fournisseurs',P(fo+fi,fo+fi)],['TVA à payer',P(tvaP,tvaP)],['Impôt sur les sociétés dû',P(is,is)],['Banque (découvert)',P(Math.max(0,-bq),Math.max(0,-bq))]];
const TA=padd(...act.map(x=>x[1])),TP=padd(...pas.map(x=>x[1])),col=(t,L)=>`<table class="t"><thead><tr><th class="l">${t}</th><th>HT</th><th>TTC</th></tr></thead><tbody>${L.map(([l,p])=>`<tr><td class="l">${l}</td><td class="num" style="color:var(--ht)">${n0(p.h)}</td><td class="num" style="color:var(--ttc)">${n0(p.t)}</td></tr>`).join('')}</tbody></table>`;
return head('Bilan simplifié','Photo de votre situation au 31 décembre '+y+', construite à partir du journal.')+`<div class="two"><div class="card">${col('Actif',act)}<table class="t"><tbody><tr class="strong"><td class="l">Total actif</td><td class="num">${n0(TA.h)}</td><td class="num">${n0(TA.t)}</td></tr></tbody></table></div><div class="card">${col('Passif',pas)}<table class="t"><tbody><tr class="strong"><td class="l">Total passif</td><td class="num">${n0(TP.h)}</td><td class="num">${n0(TP.t)}</td></tr></tbody></table></div></div><div class="card"><p style="margin:0">${Math.abs(TA.h-TP.h)<1?'<span class="chip good">Bilan équilibré</span>':'<span class="chip warn">Écart de '+e0(TA.h-TP.h)+'</span>'} Les montants du bilan sont les mêmes en HT et en TTC : il décrit des soldes. Les écritures de clôture (stocks, charges constatées d'avance, provisions) ne sont pas incluses.</p></div>`}

