function viewGroupe(){const y=S.settings.year;const R=W.companies.map(c=>withCo(c,()=>{const s=yearStats(y),T=treasury(y),rw=runway();return{c,name:S.settings.name,prof:PROFILES[S.profile],s,T,rw,al:alerts().filter(a=>a.l==='bad').length}}));
const tot=k=>R.reduce((a,r)=>padd(a,r.s[k]),P()),bH=Array(12).fill(0).map((_,i)=>sum(R.map(r=>r.T.bH[i]))),bT=Array(12).fill(0).map((_,i)=>sum(R.map(r=>r.T.bT[i])));
let h=head('Vue groupe','Vos '+W.companies.length+' entreprises côte à côte et consolidées, exercice '+y+'.');
h+=`<div class="grid">${kpi('Chiffre d\'affaires consolidé',tot('ca'))}${kpi('Résultat net consolidé',tot('rn'))}${kpi('CAF consolidée',tot('caf'))}${kpi('Trésorerie consolidée fin d\'année',P(bH[11],bT[11]))}</div>`;
h+=`<div class="card"><h2>Entreprise par entreprise</h2><div class="scroll"><table class="t"><thead><tr><th class="l">Entreprise</th><th>CA</th><th>Résultat net</th><th>CAF</th><th>Trésorerie fin</th><th>Alertes urgentes</th><th></th></tr></thead><tbody>${R.map(r=>`<tr><td class="l"><b>${esc(r.name)}</b><br><span class="note" style="margin:0">${r.prof}</span></td><td>${dual(r.s.ca)}</td><td>${dual(r.s.rn)}</td><td>${dual(r.s.caf)}</td><td>${dual(P(r.T.bH[11],r.T.bT[11]))}</td><td>${r.al?`<span class="chip bad">${r.al}</span>`:'<span class="chip good">aucune</span>'}</td><td><button data-act="goto-co" data-id="${r.c.id}">Ouvrir</button></td></tr>`).join('')}<tr class="strong"><td class="l">Total groupe</td><td>${dual(tot('ca'))}</td><td>${dual(tot('rn'))}</td><td>${dual(tot('caf'))}</td><td>${dual(P(bH[11],bT[11]))}</td><td></td><td></td></tr></tbody></table></div></div>
<div class="card"><h2>Trésorerie consolidée ${y}</h2><div class="legend"><span><b style="background:var(--ht)"></b>HT</span><span><b style="background:var(--ttc)"></b>TTC</span></div>${lineChart([{v:bH,c:'var(--ht)'},{v:bT,c:'var(--ttc)'}],MONTHS)}</div>`;
return h}
