function profileCard(){const y=S.settings.year;
if(S.profile==='ux'){const dd=docsDays(y),f=S.fl,jb=Math.round(Math.max(1,365-104-num(f.feries??8)-num(f.conges??25))*(1-num(f.nonfact??20)/100)),s=yearStats(y),kv=ratio(s.ca,1.2),T=tiersStats(y,true),ks=Object.keys(T),top=ks.sort((a,b)=>T[b].t.h-T[a].t.h)[0],sh=top&&s.ca.h>0?T[top].t.h/s.ca.h*100:0;
return `<div class="card"><h2>Votre activité de freelance</h2><div class="grid">${kpi('TJM moyen réalisé',dd.d>0?P(dd.h/dd.d,dd.h/dd.d*kv):P(num(f.tjm),num(f.tjm)*kv),dd.d>0?n0(dd.d)+' jours facturés':'TJM de référence')}<div class="kpi"><div class="kl">Taux d'occupation</div><div class="kv"><span class="h">${n0(dd.d/jb*100)} %</span></div><div class="ks">Sur ${jb} jours facturables</div></div><div class="kpi"><div class="kl">Premier client</div><div class="kv"><span class="h">${top?n0(sh)+' %':'-'}</span></div><div class="ks">${top?esc(top)+(sh>40?' : dépendance élevée':''):'Renseignez vos clients'}</div></div></div></div>`}
if(S.profile==='game'){const rw=runway(),jj=S.games.reduce((a,g)=>a+Math.max(0,num(g.avance)-gameStats(g).revNet),0),cj=S.games.reduce((a,g)=>a+CIJV_RATE*Math.min(gameStats(g).elig*num(g.cijvPart)/100,CIJV_CAP),0);
return `<div class="card"><h2>Votre studio</h2><div class="grid"><div class="kpi"><div class="kl">Runway</div><div class="kv"><span class="h">${isFinite(rw.months)?n2(rw.months)+' mois':'Rentable'}</span></div><div class="ks">Burn net : ${e0(rw.burn)} par mois</div></div>${kpi('CIJV estimé (tous jeux)',P(cj,cj),'Crédit d\'impôt jeu vidéo à 30 %')}${kpi('Avances éditeur à recouper',P(jj,jj))}</div></div>`}
return ''}
function profileAlerts(A){const y=S.settings.year;
if(S.profile==='ux'||S.profile==='gen'){const s=yearStats(y),T=tiersStats(y,true),ks=Object.keys(T);if(s.ca.h>0&&ks.length>1){const top=ks.sort((a,b)=>T[b].t.h-T[a].t.h)[0],sh=T[top].t.h/s.ca.h;if(sh>0.4)A.push({l:'warn',m:'Un seul client représente '+n0(sh*100)+' % de votre chiffre d\'affaires : '+top+'. Diversifiez pour limiter le risque.'})}
if(S.profile==='ux'){const pl=num(S.fl.plafond??83600);if(S.fl.statut==='micro'&&s.ca.h>0.85*pl)A.push({l:'warn',m:'Chiffre d\'affaires à '+n0(s.ca.h/pl*100)+' % du plafond de la micro-entreprise ('+e0(pl)+' HT).'});if(S.settings.tvaRegime==='franchise'&&s.ca.h>37500)A.push({l:'bad',m:'Seuil de franchise de TVA (37 500 € HT) dépassé : passez au régime réel.'})}}
if(S.profile==='game'){const rw=runway();if(isFinite(rw.months)&&rw.months<6)A.push({l:'bad',m:'Runway de '+n2(rw.months)+' mois : cherchez un financement ou réduisez les dépenses.'});else if(isFinite(rw.months)&&rw.months<12)A.push({l:'warn',m:'Runway de '+n2(rw.months)+' mois : anticipez le prochain jalon ou la levée.'});
S.miles.forEach(m=>{if(m.status==='prévu'&&m.date<todayISO)A.push({l:'warn',m:'Jalon éditeur « '+m.label+' » ('+m.game+') daté du '+fdate(m.date)+' non facturé.'})});S.games.forEach(g=>{const st=gameStats(g);if(num(g.budget)>0&&st.cost.h>num(g.budget)*1.05)A.push({l:'bad',m:g.name+' : coûts prévus ('+e0(st.cost.h)+') au-dessus du budget ('+e0(num(g.budget))+').'})})}}

