if(d.sal==='oui'){if(['sasu','sas','sarl','eurl'].includes(f.k)){s+=1}if(['micro','portage'].includes(f.k))s-=3}
if(d.social==='salarie'){if(['sasu','sas','portage'].includes(f.k)){s+=3;w.push('Protection sociale de salarié')}}
if(d.social==='tns'){if(['micro','ei','eurl'].includes(f.k)){s+=3;w.push('Cotisations plus faibles (TNS)')}}
const ca=num(d.ca);if(ca>0&&ca<=83600&&f.k==='micro'){s+=3;w.push('CA sous le plafond micro')}if(ca>83600&&f.k==='micro'){s-=100}
