const ikKey=f=>f.elec==='oui'&&f.veh[0]==='v'?'e'+f.veh.slice(1):f.veh;
function ikTot(key,d){const b=IKB[key];if(!b||d<=0)return 0;const s1=key[0]==='v'||key[0]==='e'?5000:3000,s2=key[0]==='v'||key[0]==='e'?20000:6000;return d<=s1?d*b[0]:d<=s2?d*b[1]+b[2]:d*b[3]}
