h+=`<div class="grid">${kpi('Devis en cours',tot,op.length+' devis')}${kpi('Valeur pondérée',w,'Montant × probabilité')}<div class="kpi"><div class="kl">Taux de transformation</div><div class="kv"><span class="h">${won+lost?n0(won/(won+lost)*100)+' %':'-'}</span></div><div class="ks">${won} gagné(s), ${lost} perdu(s)</div></div><div class="kpi"><div class="kl">Prévisionnel de trésorerie</div><div class="kv"><span class="h">${on?'Inclut le pipeline':'Sans le pipeline'}</span></div><div class="ks"><button data-act="toggle-pipe">${on?'Désactiver':'Activer'}</button></div></div></div>`;
