/* ===== LEVÉE DE FONDS ET PRÊTS : EFFET SUR LE RUNWAY ===== */
drafts.fd={kind:'levee',label:'',amount:'',date:addMonths(todayISO,3),rate:'4.5',months:'60',deferred:'6',pre:''};
const FK=[['levee','Levée de fonds (capital)'],['pret','Prêt bancaire'],['honneur','Prêt d\'honneur'],['subv','Subvention'],['avance','Avance remboursable ou préachat éditeur']];
function fundFlows(list,N){const f=Array(N).fill(0),mi=iso=>{const [y,m]=dparts(iso),[y0,m0]=dparts(todayISO);return (y-y0)*12+m-m0};
list.forEach(x=>{const a=num(x.amount),i=mi(x.date);if(['levee','subv','avance','honneur','pret'].includes(x.kind)&&i>=0&&i<N)f[i]+=a;
if(['pret','honneur'].includes(x.kind)){const n=Math.max(1,num(x.months)),d=Math.min(num(x.deferred),n-1),r=num(x.kind==='honneur'?0:x.rate)/1200,nn=n-d,pmt=r===0?a/nn:a*r/(1-Math.pow(1+r,-nn));let rest=a;for(let k=1;k<=n;k++){const it=rest*r,cap=k<=d?0:pmt-it;if(i+k<N&&i+k>=0)f[i+k]-=it+cap;rest-=cap}}
if(x.kind==='avance'){const n=24;for(let k=1;k<=n;k++)if(i+k<N)f[i+k]-=a/n}});return f}
function fundProj(list,N,cash0,net){const f=fundFlows(list,N),out=[];let c=cash0;for(let k=0;k<N;k++){c+=net+f[k];out.push(c)}return out}
const zeroAt=(a)=>{const i=a.findIndex(v=>v<0);return i<0?null:i};
function viewLevee(){const d=drafts.fd,rw=runway(),fp=S.fundp||{},cash0=fp.cash!==undefined&&fp.cash!==''?num(fp.cash):rw.cash,net=fp.net!==undefined&&fp.net!==''?num(fp.net):(rw.inn-rw.out),N=36,[y0,m0]=dparts(todayISO),lab=[];
for(let k=0;k<N;k++){const t=m0-1+k;lab.push(k%6===0?MONTHS[t%12]+' '+String(y0+Math.floor(t/12)).slice(2):'')}
const act=S.fund.filter(x=>x.on!=='non'),base=fundProj([],N,cash0,net),withF=fundProj(act,N,cash0,net),z0=zeroAt(base),z1=zeroAt(withF),mm=i=>i===null?'Plus de 36 mois':i+' mois';
let h=head('Levée de fonds et prêts','Simulez l\'effet d\'un financement sur la durée de vie de votre trésorerie (runway). Rien n\'est enregistré en comptabilité tant que vous ne cliquez pas sur « Convertir en réel ».');
h+=`<div class="grid">${kpi('Trésorerie de départ',P(cash0,cash0),'Aujourd\'hui, sans TVA sur les apports')}${kpi('Flux net mensuel',P(net,net),net<0?'Consommation mensuelle':'Excédent mensuel')}<div class="kpi"><div class="kl">Runway actuel</div><div class="kv"><span class="h">${mm(z0)}</span></div></div><div class="kpi"><div class="kl">Runway avec les financements</div><div class="kv"><span class="h">${mm(z1)}</span></div><div class="ks">${act.length} financement(s) actif(s)${z0!==null&&z1!==null&&z1>z0?' · +'+(z1-z0)+' mois':''}</div></div></div>`;
h+=`<div class="card"><h2>Trésorerie projetée sur 36 mois</h2><div class="legend"><span><b style="background:var(--muted)"></b>Sans financement</span><span><b style="background:var(--ttc)"></b>Avec financements</span></div>${lineChart([{v:base,c:'var(--muted)'},{v:withF,c:'var(--ttc)'}],lab)}<div class="row" style="margin-top:10px">${fld('Trésorerie de départ (€)',bindIn('fundp.cash',fp.cash??'',n0(rw.cash)))}${fld('Flux net mensuel (€, négatif si consommation)',bindIn('fundp.net',fp.net??'',n0(rw.inn-rw.out)))}</div><p class="note">Par défaut : trésorerie actuelle et moyenne des trois derniers mois d'encaissements moins décaissements (prêts existants inclus). Modifiez-les pour tester un plan de coûts différent, par exemple une embauche.</p></div>`;
h+=`<div class="card"><h2>Nouveau financement</h2><div class="row">${fld('Type',sel('fd.kind',FK,d.kind))}${fld('Intitulé',inp('fd.label',d.label,'placeholder="Ex. Seed, prêt BPI"'),'f2')}${fld('Montant (€)',inp('fd.amount',d.amount))}${fld('Date de réception',`<input type="date" data-draft="fd.date" value="${d.date}">`)}${['pret','honneur'].includes(d.kind)?fld('Taux annuel (%)',inp('fd.rate',d.kind==='honneur'?'0':d.rate))+fld('Durée (mois)',inp('fd.months',d.months))+fld('Différé (mois)',inp('fd.deferred',d.deferred)):''}${d.kind==='levee'?fld('Valorisation avant levée (€)',inp('fd.pre',d.pre)):''}<button class="pri" data-act="add-fund">Ajouter</button></div></div>
<div class="card"><h2>Financements simulés (${S.fund.length})</h2><div class="scroll"><table class="t"><thead><tr><th class="l">Financement</th><th class="l">Type</th><th class="l">Date</th><th>Montant</th><th class="l">Effet</th><th class="l">Actif</th><th></th></tr></thead><tbody>${S.fund.map(x=>{const a=num(x.amount),pre=num(x.pre),dil=x.kind==='levee'&&pre>0?a/(pre+a)*100:null,n=Math.max(1,num(x.months)),r=num(x.rate)/1200,d2=Math.min(num(x.deferred),n-1),nn=n-d2,pmt=r===0?a/nn:a*r/(1-Math.pow(1+r,-nn));
return `<tr><td class="l">${esc(x.label)}</td><td class="l">${esc((FK.find(k=>k[0]===x.kind)||[])[1])}</td><td class="l num">${fdate(x.date)}</td><td>${dual(P(a,a))}</td><td class="l">${dil!==null?'Dilution des fondateurs : '+n2(dil)+' %':['pret','honneur'].includes(x.kind)?'Mensualité : '+e2(pmt)+' sur '+n+' mois':x.kind==='avance'?'Remboursée sur 24 mois':'Sans remboursement'}</td><td class="l"><input type="checkbox" data-bind="fund.${S.fund.indexOf(x)}.on" data-chk="1"${x.on!=='non'?' checked':''}></td><td><button class="lnk" data-act="fund-real" data-id="${x.id}">Convertir en réel</button><button class="lnk danger" data-act="del-fund" data-id="${x.id}">Suppr.</button></td></tr>`}).join('')||'<tr><td colspan="7" class="l" style="color:var(--muted)">Aucun financement simulé.</td></tr>'}</tbody></table></div><p class="note">Les apports et les emprunts ne portent pas de TVA : HT et TTC sont identiques. Une levée de fonds est enregistrée comme apport en capital, un prêt comme emprunt (avec échéancier). Les frais de dossier, de garantie et d'avocat ne sont pas simulés.</p></div>`;return h}
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.chk&&t.dataset.bind){e.stopPropagation();setPath(S,t.dataset.bind,t.checked?'oui':'non');save();render()}},true);
EXT['add-fund']=()=>{const d=drafts.fd,a=num(d.amount,NaN);if(isNaN(a)||a<=0||!d.label.trim()){toast('Renseignez l\'intitulé et le montant.');return false}S.fund.push({id:uid(),kind:d.kind,label:d.label.trim(),amount:a,date:d.date,rate:d.kind==='honneur'?0:num(d.rate),months:num(d.months),deferred:num(d.deferred),pre:num(d.pre),on:'oui'});Object.assign(d,{label:'',amount:'',pre:''})};
EXT['del-fund']=b=>{S.fund=S.fund.filter(x=>x.id!==b.dataset.id)};
