/* ===== DOSSIER CNC, CIJV ET JEI ===== */
const CNC_STEPS=['À préparer','Demande d\'agrément provisoire déposée','Agrément provisoire obtenu','Demande d\'agrément définitif déposée','Agrément définitif obtenu','Refusé'];
const CNC_CHK=[['cout','Coût de développement d\'au moins 100 000 €'],['points','Barème culturel et européen du CNC atteint (points à vérifier auprès du CNC)'],['budget','Budget prévisionnel détaillé et plan de financement'],['contrats','Contrats de travail, de sous-traitance et de cession de droits'],['siege','Société soumise à l\'IS ou à l\'IR en France, à jour de ses obligations'],['contenu','Jeu destiné à la commercialisation, hors contenu interdit'],['dossier','Dossier d\'agrément complet déposé auprès du CNC']];
const cncOf=g=>g.cnc||(g.cnc={etape:CNC_STEPS[0],prov:'',def:'',depot:'',num:'',aides:'',delay:60,cloture:'12-31',chk:{},recv:{}});
function cijvYears(g){const c=cncOf(g),part=num(g.cijvPart??100)/100,by={};S.entries.forEach(e=>{if(e.act!==g.name||e.kind==='vente'||!CIJV_CATS.includes(e.cat))return;const y=+e.date.slice(0,4),o=by[y]||(by[y]={real:0,plan:0});if(e.date<=todayISO)o.real+=e.ht*part;else o.plan+=e.ht*part});
const total=sum(Object.values(by).map(o=>o.real+o.plan)),cost=Math.max(num(g.budget),gameStats(g).cost.h),cap80=0.8*cost,f=total>0?Math.min(1,cap80/total):1,aides=num(c.aides);
return Object.keys(by).sort().map(y=>{const o=by[y],sh=total>0?(o.real+o.plan)/total:0,net=(o.real+o.plan)*f-aides*sh,netR=o.real*f-aides*(total>0?o.real/total:0),cr=CIJV_RATE*Math.min(CIJV_CAP,Math.max(0,net)),crR=CIJV_RATE*Math.min(CIJV_CAP,Math.max(0,netR)),[mo,da]=(c.cloture||'12-31').split('-').map(Number),end=new Date(Date.UTC(+y,mo-1,da)).toISOString().slice(0,10),depot=addDays(addMonths(end,4),5),rem=addDays(depot,num(c.delay??60));return{y:+y,real:o.real,plan:o.plan,cr,crR,end,depot,rem,recv:(c.recv||{})[y]}})}
function viewCnc(){let h=head('CNC, CIJV et JEI','Suivi du dossier d\'agrément du CNC, des dépenses éligibles réelles et de la date de remboursement du crédit d\'impôt jeu vidéo, puis des conditions et des avantages de la jeune entreprise innovante. Les règles sont celles de 2026 : confirmez-les auprès du CNC et de l\'administration fiscale.');
if(!S.games.length)h+='<div class="card"><p>Créez un jeu dans « Jeux et CIJV » pour suivre son dossier.</p></div>';
S.games.forEach((g,gi)=>{const c=cncOf(g),Y=cijvYears(g),i=CNC_STEPS.indexOf(c.etape),ck=sum(CNC_CHK.map(x=>c.chk[x[0]]==='oui'?1:0)),exp=c.prov?addMonths(c.prov,36):'',left=exp?Math.round((Date.parse(exp)-Date.parse(todayISO))/864e5):null,tR=sumP(Y,x=>P(x.crR,x.crR)),tA=sumP(Y,x=>P(x.cr,x.cr));
h+=`<div class="card"><h2>${esc(g.name)}</h2><div class="grid">${kpi('Crédit sur dépenses réelles',P(tR.h,tR.h),'Dépenses éligibles déjà engagées')}${kpi('Crédit total estimé',P(tA.h,tA.h),'Dépenses réelles et prévues')}<div class="kpi"><div class="kl">Étape du dossier</div><div class="kv"><span class="h" style="font-size:16px">${esc(c.etape)}</span></div><div class="ks">${ck}/${CNC_CHK.length} pièces et conditions validées</div></div><div class="kpi"><div class="kl">Validité de l'agrément provisoire</div><div class="kv"><span class="h">${exp?fdate(exp):'-'}</span></div><div class="ks">${left===null?'36 mois à partir de l\'obtention':left<0?'<span class="chip bad">Expiré</span>':left<180?'<span class="chip warn">Expire dans '+left+' jours</span>':'<span class="chip good">'+left+' jours restants</span>'}</div></div></div>
<div class="row" style="margin-top:10px">${fld('Étape',`<select data-bind="games.${gi}.cnc.etape">${CNC_STEPS.map(s=>`<option${c.etape===s?' selected':''}>${esc(s)}</option>`).join('')}</select>`,'f2')}${fld('N° de dossier CNC',`<input type="text" data-bind="games.${gi}.cnc.num" value="${esc(c.num)}">`)}${fld('Dépôt du dossier',`<input type="date" data-bind="games.${gi}.cnc.depot" value="${c.depot||''}">`)}${fld('Agrément provisoire',`<input type="date" data-bind="games.${gi}.cnc.prov" value="${c.prov||''}">`)}${fld('Agrément définitif',`<input type="date" data-bind="games.${gi}.cnc.def" value="${c.def||''}">`)}${fld('Aides publiques reçues (€)',bindIn('games.'+gi+'.cnc.aides',c.aides))}${fld('Clôture de l\'exercice (MM-JJ)',`<input type="text" data-bind="games.${gi}.cnc.cloture" value="${esc(c.cloture)}">`)}${fld('Délai de remboursement après dépôt (jours)',bindIn('games.'+gi+'.cnc.delay',c.delay))}</div>
<div class="wraprow" style="margin:10px 0">${CNC_CHK.map(x=>`<label class="chip ${c.chk[x[0]]==='oui'?'good':''}" style="cursor:pointer"><input type="checkbox" data-bind="games.${gi}.cnc.chk.${x[0]}" data-chk="1"${c.chk[x[0]]==='oui'?' checked':''}> ${esc(x[1])}</label>`).join('')}</div>
<div class="scroll"><table class="t"><thead><tr><th class="l">Exercice</th><th>Dépenses éligibles réelles</th><th>Dépenses prévues</th><th>Crédit réel</th><th>Crédit total</th><th class="l">Liasse et formulaire 2069-A-SD</th><th class="l">Remboursement estimé</th><th class="l">Statut</th></tr></thead><tbody>${Y.map(x=>`<tr><td class="l">${x.y}</td><td>${dual(P(x.real,x.real*1.2))}</td><td>${dual(P(x.plan,x.plan*1.2))}</td><td>${dual(P(x.crR,x.crR))}</td><td>${dual(P(x.cr,x.cr))}</td><td class="l num">${fdate(x.depot)}</td><td class="l num">${fdate(x.rem)}</td><td class="l">${x.recv?'<span class="chip good">Remboursé le '+fdate(x.recv)+'</span>':`<button class="lnk" data-act="cijv-recv" data-id="${g.id}" data-y="${x.y}">Marquer remboursé</button>`}</td></tr>`).join('')||'<tr><td colspan="8" class="l" style="color:var(--muted)">Aucune dépense éligible rattachée à ce jeu.</td></tr>'}</tbody></table></div>
<div class="row" style="margin-top:10px"><button class="pri" data-act="gen-cijv" data-id="${g.id}">Inscrire le crédit estimé à la date de remboursement</button></div>
<p class="note">Dépenses éligibles : salaires, charges, sous-traitance et développement activé (comptes 641, 645, 611, 6112, 203) du jeu, au prorata de la part éligible et plafonnées à 80 % du coût total. Les montants HT et TTC du tableau sont affichés pour les dépenses ; le crédit d'impôt n'est pas soumis à la TVA. Taux de 30 %, plafond de 6 M€ par entreprise et par an, coût minimal de 100 000 €. Le crédit s'impute sur l'impôt de l'exercice, l'excédent est remboursé après le dépôt de la liasse. La date est une estimation : ajustez le délai.</p></div>`});
const J=S.jei||{},cr=J.creation||S.legal.creation||'',age=cr?(Date.parse(todayISO)-Date.parse(cr))/315576e5:null,sal=S.team.filter(m=>m.type==='salarié'),jeiM=sal.filter(m=>m.jei==='oui');
const allEl=S.entries.filter(e=>e.kind!=='vente'&&+e.date.slice(0,4)===S.settings.year),tc=sum(allEl.map(e=>e.ht)),rd=sum(allEl.filter(e=>CIJV_CATS.includes(e.cat)&&e.act).map(e=>e.ht)),pr=tc>0?rd/tc*100:0;
let cot=0;jeiM.forEach(m=>{const c=payCalc(num(m.amount),payOpts(m));cot+=c.jei*12});
h+=`<div class="card"><h2>Jeune entreprise innovante (JEI)</h2><div class="row">${fld('Date de création',`<input type="date" data-bind="jei.creation" value="${cr}">`)}${fld('Statut visé',`<select data-bind="jei.type">${['JEI','JEC','JEU','JEII','Aucun'].map(s=>`<option${(J.type||'Aucun')===s?' selected':''}>${s}</option>`).join('')}</select>`)}</div>
<div class="grid" style="margin-top:10px"><div class="kpi"><div class="kl">Ancienneté</div><div class="kv"><span class="h">${age===null?'-':n2(age)+' ans'}</span></div><div class="ks">${age===null?'Renseignez la date de création':age<8?'<span class="chip good">Moins de 8 ans</span>':'<span class="chip bad">8 ans atteints : statut impossible</span>'}</div></div><div class="kpi"><div class="kl">Dépenses de R&D, part des charges</div><div class="kv"><span class="h">${n0(pr)} %</span></div><div class="ks">${pr>=20?'<span class="chip good">20 % atteints (JEI)</span>':pr>=5?'<span class="chip warn">Entre 5 et 20 % (JEC, JEII)</span>':'<span class="chip bad">Sous 5 %</span>'}</div></div><div class="kpi"><div class="kl">Effectif</div><div class="kv"><span class="h">${sal.length}</span></div><div class="ks">${sal.length<250?'<span class="chip good">Moins de 250</span>':'<span class="chip bad">250 ou plus</span>'}</div></div>${kpi('Exonération de cotisations estimée '+S.settings.year,P(cot,cot),jeiM.length+' salarié(s) de R&D · '+(S.payp&&S.payp.jeiOn==='non'?'désactivée':'activée'))}</div>
<p class="note">Conditions : PME de moins de 250 personnes, chiffre d'affaires inférieur à 50 M€ ou bilan inférieur à 43 M€, capital détenu à 50 % par des personnes physiques ou structures éligibles, activité nouvelle, R&D d'au moins 20 % des charges (JEI). Avantages : exonération de cotisations patronales d'assurances sociales et d'allocations familiales (rémunération plafonnée à 8 401,58 € par mois, 240 300 € par an et par établissement) ; exonération d'impôt sur les bénéfices seulement pour les entreprises créées avant le 1er janvier 2024 ; exonération facultative de CFE et de taxe foncière sur délibération locale. L'option est irrévocable et se prend dans les 9 premiers mois. Désignez les salariés de R&D dans l'onglet Paie réelle.</p></div>`;return h}
EXT['cijv-recv']=b=>{const g=S.games.find(x=>x.id===b.dataset.id),c=cncOf(g);c.recv[b.dataset.y]=todayISO;const e=S.entries.find(x=>x.tpl==='cijv|'+g.id+'|'+b.dataset.y);if(e)e.paid=todayISO};
EXT['gen-cijv']=b=>{const g=S.games.find(x=>x.id===b.dataset.id);let n=0;cijvYears(g).forEach(x=>{if(x.cr<=0)return;const key='cijv|'+g.id+'|'+x.y,e=S.entries.find(q=>q.tpl===key);if(e){e.ht=r2(x.cr);e.date=x.rem;if(!S.locked[+x.rem.slice(0,4)])n++;return}if(S.locked[+x.rem.slice(0,4)])return;S.entries.push({id:uid(),date:x.rem,label:'CIJV estimé '+x.y+' – '+g.name,kind:'vente',cat:'7498',ht:r2(x.cr),rate:0,delay:0,dur:3,mode:'lin',act:g.name,tpl:key});n++});toast(n?'Crédit inscrit à la date de remboursement estimée.':'Aucun crédit à inscrire.')};
/* alertes complémentaires */
function extraAlerts(A){const miss=S.frais.filter(f=>!f.ik&&!hasJust(f)).length;if(miss)A.push({l:'warn',m:miss+' note(s) de frais sans justificatif : non déductibles tant qu\'il manque.'});
S.games.forEach(g=>{const c=g.cnc;if(!c)return;if(c.prov){const e=addMonths(c.prov,36),l=Math.round((Date.parse(e)-Date.parse(todayISO))/864e5);if(l<0)A.push({l:'bad',m:g.name+' : agrément provisoire du CNC expiré depuis le '+fdate(e)+'.'});else if(l<180)A.push({l:'warn',m:g.name+' : agrément provisoire du CNC expire le '+fdate(e)+'. Déposez la demande d\'agrément définitif.'})}
cijvYears(g).forEach(x=>{if(x.cr>0&&!x.recv&&x.rem>=todayISO&&x.rem<=addDays(todayISO,90))A.push({l:'warn',m:'Remboursement du CIJV '+x.y+' ('+g.name+') attendu vers le '+fdate(x.rem)+'.'})})});
const lateP=pipeOpen().filter(x=>x.date<todayISO).length;if(lateP)A.push({l:'warn',m:lateP+' devis du pipeline ont dépassé leur date de signature prévue : mettez-les à jour.'})}
/* re-rendu des champs de brouillon qui changent l'affichage */
document.addEventListener('change',e=>{const p=e.target.dataset.draft;if(p&&/^(st|pay|fd|fr|ik)\./.test(p)&&e.target.tagName==='SELECT')render()});
document.addEventListener('change',e=>{const p=e.target.dataset.draft;if(p&&p==='mem.mode')render()});
/* ===== FACTURATION ÉLECTRONIQUE ET E-REPORTING ===== */
const ZONES=[['fr','Entreprise assujettie en France'],['part','Particulier (B2C)'],['ue','Entreprise de l\'UE'],['hue','Hors Union européenne']];
const siren=()=>String(S.legal.siret||'').replace(/\s/g,'').slice(0,9);
const tierOf=n=>S.tiers.find(t=>t.name===n)||{};
const xe=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const dnum=iso=>iso.replace(/-/g,'');
function docXml(D){const L=S.legal,t=tierOf(D.client),fr=S.settings.tvaRegime==='franchise',tot=docTot(D),sg=D.type==='avoir'?-1:1,rates={};
D.lines.forEach(l=>{const h=num(l.q)*num(l.pu),r=fr?0:num(l.rate);rates[r]=(rates[r]||0)+h});
const unit=u=>/^jour/i.test(u||'')?'DAY':/^heure|^h$/i.test(u||'')?'HUR':'C62';
const party=(tag,name,sir,tva,addr)=>`<ram:${tag}><ram:Name>${xe(name)}</ram:Name>${sir?`<ram:SpecifiedLegalOrganization><ram:ID schemeID="0002">${xe(sir)}</ram:ID></ram:SpecifiedLegalOrganization>`:''}${addr?`<ram:PostalTradeAddress><ram:LineOne>${xe(addr)}</ram:LineOne><ram:CountryID>FR</ram:CountryID></ram:PostalTradeAddress>`:''}${tva?`<ram:SpecifiedTaxRegistration><ram:ID schemeID="VA">${xe(tva)}</ram:ID></ram:SpecifiedTaxRegistration>`:''}</ram:${tag}>`;
const items=D.lines.map((l,i)=>{const h=num(l.q)*num(l.pu),r=fr?0:num(l.rate);return `<ram:IncludedSupplyChainTradeLineItem><ram:AssociatedDocumentLineDocument><ram:LineID>${i+1}</ram:LineID></ram:AssociatedDocumentLineDocument><ram:SpecifiedTradeProduct><ram:Name>${xe(l.d)}</ram:Name></ram:SpecifiedTradeProduct><ram:SpecifiedLineTradeAgreement><ram:NetPriceProductTradePrice><ram:ChargeAmount>${num(l.pu).toFixed(2)}</ram:ChargeAmount></ram:NetPriceProductTradePrice></ram:SpecifiedLineTradeAgreement><ram:SpecifiedLineTradeDelivery><ram:BilledQuantity unitCode="${unit(l.u)}">${num(l.q)}</ram:BilledQuantity></ram:SpecifiedLineTradeDelivery><ram:SpecifiedLineTradeSettlement><ram:ApplicableTradeTax><ram:TypeCode>VAT</ram:TypeCode><ram:CategoryCode>${r>0?'S':'E'}</ram:CategoryCode><ram:RateApplicablePercent>${r.toFixed(2)}</ram:RateApplicablePercent></ram:ApplicableTradeTax><ram:SpecifiedTradeSettlementLineMonetarySummation><ram:LineTotalAmount>${h.toFixed(2)}</ram:LineTotalAmount></ram:SpecifiedTradeSettlementLineMonetarySummation></ram:SpecifiedLineTradeSettlement></ram:IncludedSupplyChainTradeLineItem>`}).join('');
const taxes=Object.entries(rates).map(([r,b])=>`<ram:ApplicableTradeTax><ram:CalculatedAmount>${(b*r/100).toFixed(2)}</ram:CalculatedAmount><ram:TypeCode>VAT</ram:TypeCode>${+r>0?'':'<ram:ExemptionReason>TVA non applicable, art. 293 B du CGI</ram:ExemptionReason>'}<ram:BasisAmount>${b.toFixed(2)}</ram:BasisAmount><ram:CategoryCode>${+r>0?'S':'E'}</ram:CategoryCode><ram:RateApplicablePercent>${(+r).toFixed(2)}</ram:RateApplicablePercent></ram:ApplicableTradeTax>`).join('');
const ttc=fr?tot.h:tot.t;
return `<?xml version="1.0" encoding="UTF-8"?>\n<rsm:CrossIndustryInvoice xmlns:rsm="urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100" xmlns:ram="urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100" xmlns:udt="urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100"><rsm:ExchangedDocumentContext><ram:GuidelineSpecifiedDocumentContextParameter><ram:ID>urn:factur-x.eu:1p0:basic</ram:ID></ram:GuidelineSpecifiedDocumentContextParameter></rsm:ExchangedDocumentContext><rsm:ExchangedDocument><ram:ID>${xe(D.num)}</ram:ID><ram:TypeCode>${D.type==='avoir'?'381':'380'}</ram:TypeCode><ram:IssueDateTime><udt:DateTimeString format="102">${dnum(D.date)}</udt:DateTimeString></ram:IssueDateTime></rsm:ExchangedDocument><rsm:SupplyChainTradeTransaction>${items}<ram:ApplicableHeaderTradeAgreement>${party('SellerTradeParty',L.raison||S.settings.name,siren(),L.tva,L.adresse)}${party('BuyerTradeParty',D.client,String(t.siren||'').replace(/\s/g,''),t.tva,t.addr)}</ram:ApplicableHeaderTradeAgreement><ram:ApplicableHeaderTradeDelivery/><ram:ApplicableHeaderTradeSettlement><ram:InvoiceCurrencyCode>EUR</ram:InvoiceCurrencyCode>${taxes}<ram:SpecifiedTradePaymentTerms><ram:DueDateDateTime><udt:DateTimeString format="102">${dnum(dueOf(D))}</udt:DateTimeString></ram:DueDateDateTime></ram:SpecifiedTradePaymentTerms><ram:SpecifiedTradeSettlementHeaderMonetarySummation><ram:LineTotalAmount>${tot.h.toFixed(2)}</ram:LineTotalAmount><ram:TaxBasisTotalAmount>${tot.h.toFixed(2)}</ram:TaxBasisTotalAmount><ram:TaxTotalAmount currencyID="EUR">${(ttc-tot.h).toFixed(2)}</ram:TaxTotalAmount><ram:GrandTotalAmount>${ttc.toFixed(2)}</ram:GrandTotalAmount><ram:DuePayableAmount>${ttc.toFixed(2)}</ram:DuePayableAmount></ram:SpecifiedTradeSettlementHeaderMonetarySummation></ram:ApplicableHeaderTradeSettlement></rsm:SupplyChainTradeTransaction></rsm:CrossIndustryInvoice>`}
function docCheck(D){const t=tierOf(D.client),w=[];if(!siren()||siren().length<9)w.push('SIREN du vendeur');if((t.zone||'fr')==='fr'&&!String(t.siren||'').replace(/\s/g,'').match(/^\d{9}$/))w.push('SIREN du client');if(!S.legal.adresse)w.push('adresse du vendeur');if(!t.addr)w.push('adresse du client');return w}
function viewEfact(){const y=S.settings.year,st=S.settings,eti=st.taille==='eti',emit=eti?'2026-09-01':'2027-09-01',days=Math.round((Date.parse(emit)-Date.parse(todayISO))/864e5);
let h=head('Facture électronique et e-reporting','Préparez la réforme : réception obligatoire, émission selon votre taille, transmission des données par une plateforme agréée. L\'application produit les fichiers ; l\'envoi à l\'administration passe par votre plateforme agréée.');
h+=`<div class="grid"><div class="kpi"><div class="kl">Réception de factures électroniques</div><div class="kv"><span class="h">01/09/2026</span></div><div class="ks">${todayISO>='2026-09-01'?'<span class="chip bad">Obligatoire depuis le 1er septembre 2026</span>':'À venir'}</div></div><div class="kpi"><div class="kl">Émission pour votre entreprise</div><div class="kv"><span class="h">${fdate(emit)}</span></div><div class="ks">${days>0?'<span class="chip warn">Dans '+days+' jours</span>':'<span class="chip bad">Obligatoire</span>'}</div></div><div class="kpi"><div class="kl">Plateforme agréée</div><div class="kv"><span class="h" style="font-size:16px">${esc(st.pdp||'Non choisie')}</span></div><div class="ks">${st.pdp?'<span class="chip good">Choisie</span>':'<span class="chip bad">À choisir</span>'}</div></div></div>
<div class="card"><h2>Votre situation</h2><div class="row">${fld('Catégorie d\'entreprise',`<select data-bind="settings.taille"><option value="pme"${!eti?' selected':''}>Micro-entreprise ou PME</option><option value="eti"${eti?' selected':''}>Grande entreprise ou ETI</option></select>`,'f2')}${fld('Plateforme agréée choisie',`<input type="text" data-bind="settings.pdp" value="${esc(st.pdp||'')}" placeholder="Nom de la plateforme">`,'f2')}</div><p class="note">Calendrier : toutes les entreprises doivent pouvoir recevoir des factures électroniques depuis le 1er septembre 2026. L'émission est obligatoire le 1er septembre 2026 pour les grandes entreprises et les ETI, le 1er septembre 2027 pour les PME et les micro-entreprises. Les opérations avec des particuliers ou des clients étrangers relèvent de l'e-reporting. Source : service-public.fr. Le détail des mentions obligatoires (SIREN du client, catégorie d'opération, option TVA sur les débits, adresse de livraison) est à contrôler dans le guide de la DGFiP.</p></div>`;
const T=S.tiers.map((t,i)=>({t,i}));
h+=`<div class="card"><h2>Fiches clients : zone et SIREN</h2><div class="scroll"><table class="t"><thead><tr><th class="l">Client</th><th class="l">Zone</th><th class="l">SIREN</th><th class="l">N° TVA</th></tr></thead><tbody>${T.map(({t,i})=>`<tr><td class="l">${esc(t.name)}</td><td class="l"><select data-bind="tiers.${i}.zone">${ZONES.map(z=>`<option value="${z[0]}"${(t.zone||'fr')===z[0]?' selected':''}>${z[1]}</option>`).join('')}</select></td><td class="l"><input type="text" data-bind="tiers.${i}.siren" value="${esc(t.siren||'')}" style="width:120px"></td><td class="l"><input type="text" data-bind="tiers.${i}.tva" value="${esc(t.tva||'')}"></td></tr>`).join('')||'<tr><td colspan="4" class="l" style="color:var(--muted)">Les fiches se créent avec vos factures.</td></tr>'}</tbody></table></div></div>`;
const F=S.docs.filter(D=>D.type!=='devis'&&+D.date.slice(0,4)===y).sort((a,b)=>a.date.localeCompare(b.date));
h+=`<div class="card"><h2>Factures ${y} : flux électronique</h2><div class="scroll"><table class="t"><thead><tr><th class="l">Numéro</th><th class="l">Client</th><th>TTC</th><th class="l">Flux</th><th class="l">Contrôle</th><th class="l">Transmission</th><th></th></tr></thead><tbody>${F.map(D=>{const t=tierOf(D.client),z=t.zone||'fr',w=docCheck(D),tot=docTot(D);return `<tr><td class="l">${esc(D.num)}</td><td class="l">${esc(D.client)}</td><td>${dual(tot)}</td><td class="l">${z==='fr'?'Facture électronique':'E-reporting'}</td><td class="l">${w.length?'<span class="chip warn">Manque : '+esc(w.join(', '))+'</span>':'<span class="chip good">Complet</span>'}</td><td class="l">${D.ef==='transmis'?'<span class="chip good">Transmise</span>':'<span class="chip">À transmettre</span>'}</td><td><button class="lnk" data-act="efact-xml" data-id="${D.id}">XML</button>${D.ef==='transmis'?'':`<button class="lnk" data-act="efact-ok" data-id="${D.id}">Marquer transmise</button>`}</td></tr>`}).join('')||'<tr><td colspan="7" class="l" style="color:var(--muted)">Aucune facture cette année.</td></tr>'}</tbody></table></div>
<p class="note">Le fichier XML suit la syntaxe CII du profil Factur-X BASIC. Un Factur-X complet associe ce XML à un PDF/A-3 : votre plateforme agréée le génère ou le convertit. Faites valider un fichier test par votre plateforme avant la date d'obligation.</p></div>`;
const R=S.entries.filter(e=>e.kind==='vente'&&+e.date.slice(0,4)===y&&!e.pipe&&(tierOf(e.tiers).zone||'fr')!=='fr');
h+=`<div class="card"><h2>Registre e-reporting ${y} (${R.length})</h2><div class="scroll"><table class="t"><thead><tr><th class="l">Date</th><th class="l">Libellé</th><th class="l">Client</th><th class="l">Nature</th><th>Montant</th><th class="l">Paiement</th></tr></thead><tbody>${R.sort((a,b)=>a.date.localeCompare(b.date)).slice(0,60).map(e=>`<tr><td class="l num">${fdate(e.date)}</td><td class="l">${esc(e.label)}</td><td class="l">${esc(e.tiers)}</td><td class="l">${tierOf(e.tiers).zone==='part'?'Vente à un particulier':'Opération internationale'}</td><td>${dual(P(e.ht,tt(e)))}</td><td class="l">${e.paid?fdate(e.paid):'à encaisser'}</td></tr>`).join('')||'<tr><td colspan="6" class="l" style="color:var(--muted)">Aucune opération à déclarer : classez vos clients (particulier, UE, hors UE) ci-dessus.</td></tr>'}</tbody></table></div><div class="row" style="margin-top:10px"><button data-act="efact-csv">Exporter le registre en CSV</button></div><p class="note">À transmettre à l'administration par la plateforme : données de transaction des ventes aux particuliers et à l'étranger, et données de paiement des prestations de services. La fréquence dépend de votre régime de TVA : confirmez-la avec votre plateforme.</p></div>`;return h}
