const PAYS={FR:['France',20],DE:['Allemagne',19],ES:['Espagne',21],IT:['Italie',22],BE:['Belgique',21],NL:['Pays-Bas',21],PT:['Portugal',23],AT:['Autriche',20],IE:['Irlande',23],LU:['Luxembourg',17],PL:['Pologne',23],SE:['Suède',25],DK:['Danemark',25],FI:['Finlande',25.5],GR:['Grèce',24],CZ:['Tchéquie',21],HU:['Hongrie',27],RO:['Roumanie',21],BG:['Bulgarie',20],HR:['Croatie',25],SK:['Slovaquie',23],SI:['Slovénie',22],LT:['Lituanie',21],LV:['Lettonie',21],EE:['Estonie',24],CY:['Chypre',19],MT:['Malte',18],US:['États-Unis',0],GB:['Royaume-Uni',0],CH:['Suisse',0],CA:['Canada',0],JP:['Japon',0]};
