function ossCalc(y){const m={};let ttc=0,ht=0,tva=0,tot=0;S.vplat.forEach(v=>{if(v.canal!=='direct'||+v.date.slice(0,4)!==y)return;tot++;const r=(PAYS[v.pays]||['',0])[1],t=num(v.units)*num(v.ttcUnit),h=t/(1+r/100);const o=m[v.pays]||(m[v.pays]={n:(PAYS[v.pays]||[v.pays])[0],r,ttc:0,ht:0,tva:0});o.ttc+=t;o.ht+=h;o.tva+=t-h;if(isEU(v.pays)){ttc+=t;ht+=h;tva+=t-h}});return{rows:Object.values(m),ttc,ht,tva,tot}}
