EXT['pj-paper']=b=>{const e=S.entries.find(x=>x.id===b.dataset.id);e.justif='papier'};
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.ext!=='pj-up')return;const f=t.files[0],en=S.entries.find(x=>x.id===t.dataset.id);if(!f||!en)return;if(!ASSETS){toast('Envoi de fichiers indisponible ici.');return}try{const r=await ASSETS.upload(f);en.att={id:r.id,url:r.url,name:f.name,at:todayISO};save();render();toast('Justificatif archivé.')}catch(err){toast('Envoi impossible (droits d\'édition requis).')}});

