/* ===== RETARDS DE PAIEMENT ET RELANCES ===== */
const dd=(a,b)=>Math.round((Date.parse(b)-Date.parse(a))/864e5);
function lateStats(){const m={};S.entries.forEach(e=>{if(e.kind!=='vente'||!e.tiers||e.tpl||e.pipe)return;if(e.paid&&e.paid<=todayISO){const late=Math.max(0,dd(addDays(e.date,e.delay||0),e.paid)),o=m[e.tiers]||(m[e.tiers]={n:0,s:0,l:0});o.n++;o.s+=late;if(late>3)o.l++}});Object.values(m).forEach(o=>{o.avg=o.n?o.s/o.n:0;o.pct=o.n?o.l/o.n*100:0});return m}
function lateShift(e,L){const o=L[e.tiers];return o&&o.n>=2?Math.round(o.avg):0}
function viewRetards(){const L=lateStats(),st=S.settings,od=S.entries.filter(e=>e.kind==='vente'&&!e.paid&&!e.pipe&&!e.tpl&&cashDate(e)<todayISO&&e.date<=todayISO).map(e=>({e,late:dd(cashDate(e),todayISO)})).sort((a,b)=>b.late-a.late),tot=od.reduce((a,x)=>padd(a,P(x.e.ht,tt(x.e))),P());
ui.relMsgs=[];const L_=S.legal;
let h=head('Retards de paiement et relances','Probabilité de retard par client déduite de votre historique, effet sur les encaissements prévus, et relances prêtes à envoyer avec les pénalités légales.');
h+=`<div class="grid">${kpi('Impayés échus',tot,od.length+' pièce(s) en retard')}<div class="kpi"><div class="kl">Prévision tenant compte des retards</div><div class="kv"><span class="h">${st.usePredict?'Activée':'Désactivée'}</span></div><div class="ks"><button data-act="toggle-pred">${st.usePredict?'Désactiver':'Activer'}</button></div></div></div>
<div class="card"><h2>Comportement de paiement par client</h2><div class="scroll"><table class="t"><thead><tr><th class="l">Client</th><th>Factures payées</th><th>Retard moyen</th><th>Part payée en retard</th><th class="l">Décalage appliqué</th></tr></thead><tbody>${Object.keys(L).sort((a,b)=>L[b].avg-L[a].avg).map(k=>`<tr><td class="l">${esc(k)}</td><td>${L[k].n}</td><td>${n0(L[k].avg)} j</td><td>${n0(L[k].pct)} %</td><td class="l">${L[k].n>=2?'+'+Math.round(L[k].avg)+' jours':'<span class="note" style="margin:0">Historique insuffisant</span>'}</td></tr>`).join('')||'<tr><td colspan="5" class="l" style="color:var(--muted)">Aucun paiement enregistré : marquez des factures comme payées pour alimenter l\'historique.</td></tr>'}</tbody></table></div><p class="note">Quand la prévision est activée, chaque encaissement non réglé d'un client avec au moins deux paiements est décalé de son retard moyen dans le tableau de trésorerie.</p></div>`;
h+=`<div class="card"><h2>Relances à envoyer (${od.length})</h2><div class="scroll"><table class="t"><thead><tr><th class="l">Pièce</th><th class="l">Client</th><th>Montant</th><th>Retard</th><th class="l">Niveau</th><th></th></tr></thead><tbody>${od.slice(0,40).map(x=>{const e=x.e,t=tt(e),lv=x.late<=7?'Rappel amiable':x.late<=30?'Relance':'Mise en demeure',pen=lv==='Mise en demeure'?' L\'indemnité forfaitaire de recouvrement de 40 € et les pénalités de retard (trois fois le taux d\'intérêt légal) sont exigibles.':'';ui.relMsgs.push(`Objet : ${lv} – ${e.label}\n\nBonjour,\n\nSauf erreur de notre part, la somme de ${n2(t)} € TTC (${n2(e.ht)} € HT) relative à « ${e.label} », échue le ${fdate(cashDate(e))}, n'a pas été réglée à ce jour (${x.late} jours de retard).${pen}\n\nMerci de procéder au règlement dans les meilleurs délais${L_.iban?' par virement (IBAN '+L_.iban+')':''}.\n\nCordialement,\n${L_.raison||st.name}`);return `<tr><td class="l">${esc(e.label)}</td><td class="l">${esc(e.tiers||'-')}</td><td>${dual(P(e.ht,t))}</td><td>${x.late} j</td><td class="l"><span class="chip ${lv==='Rappel amiable'?'':lv==='Relance'?'warn':'bad'}">${lv}</span></td><td><button class="lnk" data-act="copy-rel" data-i="${ui.relMsgs.length-1}">Copier le message</button></td></tr>`}).join('')||'<tr><td colspan="6" class="l" style="color:var(--muted)">Aucun retard.</td></tr>'}</tbody></table></div></div>`;return h}
EXT['toggle-pred']=()=>{S.settings.usePredict=!S.settings.usePredict;ver++};
EXT['copy-rel']=b=>{const t=(ui.relMsgs||[])[+b.dataset.i]||'';try{navigator.clipboard.writeText(t).then(()=>toast('Message copié.')).catch(()=>toast('Copie refusée : sélectionnez le texte manuellement.'))}catch(e){toast('Copie indisponible.')}return false};

/* ===== FORECAST GLISSANT ===== */
function glissCalc(y){const now=new Date(),cm=now.getFullYear()===y?now.getMonth():y<now.getFullYear()?11:-1,cats={};
E().forEach(e=>{if(+e.date.slice(0,4)!==y||e.kind==='vente')return;const m=+e.date.slice(5,7)-1,o=cats[e.cat]||(cats[e.cat]={real:Array(12).fill(0),plan:Array(12).fill(0)});if(e.date<=todayISO)o.real[m]+=e.ht;else o.plan[m]+=e.ht});
const rows=Object.keys(cats).sort().map(k=>{const o=cats[k],real=sum(o.real),planned=sum(o.plan),rem=11-cm,last=o.real.slice(Math.max(0,cm-2),cm+1),rr=last.length?sum(last)/last.length:0,fc=real+(planned>0||cm>=11?planned:rr*Math.max(0,rem)),b=num((S.catBudget||{})[k]);return{k,real,planned,fc,b,dev:b>0?(fc-b)/b*100:null,trend:planned===0&&cm<11}});return{rows,cm}}
function viewGliss(){const y=S.settings.year,G=glissCalc(y),tot=G.rows.reduce((a,r)=>({real:a.real+r.real,fc:a.fc+r.fc,b:a.b+r.b}),{real:0,fc:0,b:0});
let h=head('Forecast glissant','Le réalisé remplace le prévu au fil des mois ; le reste de l\'année est projeté à partir des pièces planifiées ou, à défaut, de la tendance des trois derniers mois. Comparaison au budget par catégorie.');
const lab=MONTHS,cum=Array(12).fill(0);E().forEach(e=>{if(+e.date.slice(0,4)===y&&e.kind!=='vente')cum[+e.date.slice(5,7)-1]+=e.ht});let c=0;const cc=cum.map(v=>c+=v),bm=tot.b/12,bl=lab.map((_,i)=>bm*(i+1));
h+=`<div class="grid">${kpi('Dépenses réalisées',P(tot.real,tot.real*1.2))}${kpi('Forecast de fin d\'année',P(tot.fc,tot.fc*1.2),'Réalisé + projection')}${kpi('Budget annuel',P(tot.b,tot.b*1.2))}<div class="kpi"><div class="kl">Écart forecast / budget</div><div class="kv"><span class="h">${tot.b>0?n0((tot.fc-tot.b)/tot.b*100)+' %':'-'}</span></div><div class="ks">${tot.b>0&&tot.fc>tot.b*1.1?'<span class="chip bad">Dérapage</span>':tot.b>0?'<span class="chip good">Maîtrisé</span>':'Saisissez des budgets'}</div></div></div>`;
if(tot.b>0)h+=`<div class="card"><h2>Dépenses cumulées HT ${y}</h2><div class="legend"><span><b style="background:var(--ttc)"></b>Réalisé et prévu</span><span><b style="background:var(--muted)"></b>Budget</span></div>${lineChart([{v:cc,c:'var(--ttc)'},{v:bl,c:'var(--muted)'}],lab)}</div>`;
h+=`<div class="card"><h2>Par catégorie</h2><div class="scroll"><table class="t"><thead><tr><th class="l">Catégorie</th><th>Budget HT</th><th>Réalisé HT</th><th>Planifié HT</th><th>Forecast HT</th><th>Forecast TTC</th><th>Écart</th></tr></thead><tbody>${G.rows.map(r=>`<tr><td class="l">${r.k} · ${esc(catOf(r.k)?.n||'')}</td><td><input type="text" inputmode="decimal" data-bind="catBudget.${r.k}" data-num="1" value="${esc((S.catBudget||{})[r.k]??'')}" style="width:96px"></td><td>${n0(r.real)}</td><td>${n0(r.planned)}</td><td>${n0(r.fc)}${r.trend?' <span class="note" style="margin:0">tendance</span>':''}</td><td>${n0(r.fc*(1+(catOf(r.k)?.r??20)/100))}</td><td>${r.dev===null?'-':`<span class="chip ${r.dev>10?'bad':r.dev>0?'warn':'good'}">${r.dev>0?'+':''}${n0(r.dev)} %</span>`}</td></tr>`).join('')}</tbody></table></div><p class="note">Forecast = réalisé à ce jour + pièces planifiées ; sans pièce planifiée, tendance moyenne des trois derniers mois × mois restants. Le TTC applique le taux par défaut de la catégorie.</p></div>`;return h}
function glissAlerts(A){const G=glissCalc(S.settings.year);G.rows.forEach(r=>{if(r.dev!==null&&r.dev>10&&r.b>0)A.push({l:'warn',m:'Poste « '+(catOf(r.k)?.n||r.k)+' » : forecast '+e0(r.fc)+' HT, '+n0(r.dev)+' % au-dessus du budget de '+e0(r.b)+'.'})})}
/* ===== INDICATEURS STUDIO : VENTES PAR PLATEFORME, CAC, ARPU ===== */
const PLATS=[['steam','Steam',30],['epic','Epic Games Store',12],['apple','App Store',30],['google','Google Play',30],['switch','Nintendo eShop',30],['ps','PlayStation Store',30],['xbox','Xbox Store',30],['itch','itch.io',10],['direct','Boutique propre',3]];
drafts.vp={game:'',plat:'steam',canal:'plateforme',date:todayISO,pays:'FR',units:'',ttcUnit:'19.99'};
