<div class="row" style="margin-top:10px">${fld('Aide',inp('ai.label',d.label),'f2')}${fld('Organisme',inp('ai.org',d.org))}${fld('Nature',sel('ai.type',[['subvention','Subvention'],['avance','Avance remboursable'],['pret','Prêt']],d.type))}${fld('Montant (€)',inp('ai.amount',d.amount))}${fld('Statut',sel('ai.statut',AIDE_ST.map(s=>[s,s]),d.statut))}<button class="pri" data-act="add-aide">Ajouter</button></div>
