/* ===== RÉMUNÉRATION DU DIRIGEANT ===== */
function remuSim(){const f=S.fl,y=S.settings.year,s=yearStats(y),r=S.rm||{},B=r.B!==undefined&&r.B!==''?num(r.B):Math.max(0,simStatuts().B),sasu=(r.st||'sasu')==='sasu',tns=(f.tns??45)/100,pat=(f.pat??42)/100,sal=(f.sal??22)/100,pfu=(f.pfu??31.4)/100,parts=f.parts||1,seuil=150*12.02,out=[];
for(let i=0;i<=10;i++){const sh=i/10,R=B*sh;let net0,cot,brutRef;if(sasu){const brut=R/(1+pat);net0=brut*(1-sal);cot=R-net0;brutRef=brut}else{net0=R/(1+tns);cot=R-net0;brutRef=net0}
const irr=irCalc(net0*0.9,parts),pr=B-R,is=isCalc(pr),div=pr-is,divNet=div*(1-pfu),net=net0-irr+divNet,q=Math.min(4,Math.floor(brutRef/seuil));out.push({sh,R,net0,irr,is,div,divNet,net,cot,q,taxes:cot+irr+is+div*pfu})}
return{B,sasu,out,seuilAn:seuil*4}}
function viewRemu(){const S_=remuSim(),r=S.rm||{},best=S_.out.reduce((a,b)=>b.net>a.net?b:a),minQ=S_.out.find(x=>x.q>=4)||S_.out[S_.out.length-1],pf=S.fl.pfu??31.4;
let h=head('Rémunération du dirigeant','Quel partage entre salaire (ou rémunération) et dividendes ? Net en poche après cotisations, impôt sur les sociétés, impôt sur le revenu et flat tax, avec l\'effet sur la validation des trimestres de retraite.');
h+=`<div class="card"><div class="row">${fld('Statut',`<select data-bind="rm.st"><option value="sasu"${S_.sasu?' selected':''}>SASU ou SAS (assimilé salarié)</option><option value="eurl"${!S_.sasu?' selected':''}>EURL ou SARL (gérant majoritaire, TNS)</option></select>`,'f2')}${fld('Résultat avant rémunération (€)',bindIn('rm.B',r.B??'',n0(S_.B)))}${fld('Flat tax sur dividendes (%)',bindIn('fl.pfu',pf))}${fld('Parts fiscales',bindIn('fl.parts',S.fl.parts??1))}${fld('Cotisations TNS (% du net)',bindIn('fl.tns',S.fl.tns??45))}${fld('Charges patronales (%)',bindIn('fl.pat',S.fl.pat??42))}${fld('Charges salariales (%)',bindIn('fl.sal',S.fl.sal??22))}</div></div>`;
h+=`<div class="grid">${kpi('Net maximum en poche',P(best.net,best.net),'Pour '+n0(best.sh*100)+' % du résultat en rémunération')}${kpi('Net avec 4 trimestres validés',P(minQ.net,minQ.net),'Rémunération de '+n0(minQ.sh*100)+' % du résultat')}${kpi('Écart de net',P(best.net-minQ.net,best.net-minQ.net),'Le prix de la protection sociale')}</div>`;
h+=`<div class="card"><h2>Net en poche selon la part de rémunération</h2>${lineChart([{v:S_.out.map(x=>x.net),c:'var(--ttc)'}],S_.out.map(x=>n0(x.sh*100)+' %'))}<div class="scroll"><table class="t"><thead><tr><th class="l">Part du résultat en rémunération</th><th>Coût de la rémunération</th><th>Net après cotisations</th><th>Impôt sur le revenu</th><th>IS</th><th>Dividendes nets</th><th>Net total</th><th>Trimestres</th></tr></thead><tbody>${S_.out.map(x=>`<tr class="${x===best?'strong':''}"><td class="l">${n0(x.sh*100)} %</td><td>${n0(x.R)}</td><td>${n0(x.net0)}</td><td>${n0(x.irr)}</td><td>${n0(x.is)}</td><td>${n0(x.divNet)}</td><td>${n0(x.net)}</td><td>${x.q} / 4</td></tr>`).join('')}</tbody></table></div>
<p class="note">Sans TVA : HT et TTC identiques. Trimestre de retraite validé à partir de 150 heures de SMIC horaire (12,02 €) de rémunération soit environ ${e0(S_.seuilAn)} par an pour 4 trimestres. ${S_.sasu?'Le président de SASU cotise aux régimes salariés (maladie, retraite, prévoyance) mais n\'a pas droit au chômage ; les dividendes ne supportent que la flat tax.':'Le gérant TNS cotise sur sa rémunération et, au-delà de 10 % du capital social, sur ses dividendes : cet effet n\'est pas inclus ici ; sa protection sociale (indemnités journalières, retraite) est généralement plus faible.'} Simulation indicative : ne remplace pas le conseil de votre expert-comptable. Taux de flat tax à vérifier (31,4 % depuis 2026).</p></div>`;return h}
