/* ===== compression et démarrage ===== */
async function pack(o){const json=JSON.stringify(o);if(typeof CompressionStream==='undefined')return{v:1,json};
try{const cs=new CompressionStream('gzip'),w=cs.writable.getWriter();w.write(new TextEncoder().encode(json));w.close();const buf=new Uint8Array(await new Response(cs.readable).arrayBuffer());let b='';for(let i=0;i<buf.length;i+=8192)b+=String.fromCharCode.apply(null,buf.subarray(i,i+8192));return{v:1,z:btoa(b)}}catch(e){return{v:1,json}}}
async function unpack(d){if(d.z){const bin=atob(d.z),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);const ds=new DecompressionStream('gzip'),w=ds.writable.getWriter();w.write(u);w.close();return JSON.parse(await new Response(ds.readable).text())}
if(d.json)return JSON.parse(d.json);if(typeof d.data==='string')return JSON.parse(d.data);return d}
document.addEventListener('change',async e=>{const t=e.target,x=t.dataset.ext,k=t.dataset.dr2;
if(k){const d=drafts.tpl;if(k==='tpl.kind'){d.kind=t.value;const c=catsFor(d.kind)[0];d.cat=c.a;d.rate=c.r;render()}return}
if(!x)return;
if(x==='scen'){S.scen.cur=t.value;save();render()}
else if(x==='scenp'){const p=S.scen.list[t.dataset.n];if(p){p[t.dataset.k]=num(t.value);save();render()}}
else if(x==='imp'){const r=ui.imp[+t.dataset.i],f=t.dataset.f;if(f==='on')r.on=t.checked;else if(f==='cat'){r.cat=t.value;r.rate=catOf(t.value).r;render()}else if(f==='rate'){r.rate=num(t.value);render()}else r.kw=t.value}
else if(x==='bank-file'){const f=t.files[0];if(f){ui.impText=await f.text();ui.imp=parseBank(ui.impText);render()}}
else if(x==='att'){const f=t.files[0];if(!f||!ASSETS)return;try{const r=await ASSETS.upload(f);drafts.entry.att={id:r.id,url:r.url,name:f.name,at:todayISO};render()}catch(err){toast('Envoi impossible (droits d\'édition requis).')}}});
